action.param:
"if (!document.querySelector(`script[src='${#0}']`)) {
  let file = document.createElement('script')
  file.setAttribute('type','text/javascript')
  file.setAttribute('src', #0)
  file.onload = ()=> {file.onload = null; c2_callFunction('JS_OnLoad', [#0])}
  file.onerror = ()=> console.error(`failed including ${#0}`)
  document.getElementsByTagName('head')[0].appendChild(file)
}"

JS.JSCodeValue("(()=>{
let string = decodeURIComponent(#0)
let canvas = document.createElement('canvas')
let context = canvas.getContext('2d')
context.font = #1 + 'px Arial'
return context.measureText(string).width
})()", replace(Function.Param(0), "'", "%27"), ceil(Function.Param(1) * 1.33))

JS.JSCodeValue("(()=>{
let array = JSON.parse(#0)
for (let i = array.length - 1; i >= 0; i--) {
    let j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]]
}
return JSON.stringify(array)
})()", Function.Param(0))

JS.JSCodeValue("(()=>{
let array = JSON.parse(#0)
array.splice(#1, 1)
return JSON.stringify(array)
})()", Function.Param(0), Function.Param(1))

JS.JSCodeValue("(()=>{
let array = JSON.parse(#0)
let index = array.indexOf(#1)
if (index > -1) array.splice(index, 1)
return JSON.stringify(array)
})()", Function.Param(0), Function.Param(1))
